import{_ as a,o as r,c as s,a6 as n}from"./chunks/framework.BrkgobfX.js";const u=JSON.parse('{"title":"量化与排查 · TTFB、LCP 与缓存命中率","description":"SSR 上了生产，该盯哪些指标、怎么排查慢？这一章讲清 TTFB、FCP、LCP、INP 各测什么，以及 SSR 独有的健康指标——缓存命中率；再给一套「页面慢，是服务端还是水合的锅」的排查流程。","frontmatter":{"title":"量化与排查 · TTFB、LCP 与缓存命中率","description":"SSR 上了生产，该盯哪些指标、怎么排查慢？这一章讲清 TTFB、FCP、LCP、INP 各测什么，以及 SSR 独有的健康指标——缓存命中率；再给一套「页面慢，是服务端还是水合的锅」的排查流程。","source":"https://daiw.org/manual/ssr/measuring"},"headers":[],"relativePath":"manual/computer-programming/ssr/measuring.md","filePath":"manual/computer-programming/ssr/measuring.md"}'),e={name:"manual/computer-programming/ssr/measuring.md"};function o(l,t,i,p,d,g){return r(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="量化与排查-·-ttfb、lcp-与缓存命中率" tabindex="-1">量化与排查 · TTFB、LCP 与缓存命中率 <a class="header-anchor" href="#量化与排查-·-ttfb、lcp-与缓存命中率" aria-label="Permalink to &quot;量化与排查 · TTFB、LCP 与缓存命中率&quot;">​</a></h1><p>SSR 上了生产，该盯哪些指标、怎么排查慢？这一章讲清 TTFB、FCP、LCP、INP 各测什么，以及 SSR 独有的健康指标——缓存命中率；再给一套「页面慢，是服务端还是水合的锅」的排查流程。</p><p>前面把 SSR 的渲染与缓存讲透了。最后一站落地：这些东西上了生产，<strong>你该盯哪些数字，慢了又该怎么排查。</strong> 不会量化，再多理论也落不了地。</p><h2 id="该盯的几个指标" tabindex="-1">该盯的几个指标 <a class="header-anchor" href="#该盯的几个指标" aria-label="Permalink to &quot;该盯的几个指标&quot;">​</a></h2><p>SSR 的性能，拆在一条「从请求到可交互」的时间线上，各有各的表：</p><table tabindex="0"><thead><tr><th>指标</th><th>全称</th><th>测什么</th><th>主要受什么影响</th></tr></thead><tbody><tr><td><strong>TTFB</strong></td><td>Time To First Byte</td><td>请求发出到收到第一个字节</td><td><strong>服务端渲染 + 缓存</strong>（SSR 的核心）</td></tr><tr><td><strong>FCP</strong></td><td>First Contentful Paint</td><td>首次画出内容</td><td>TTFB + 关键资源</td></tr><tr><td><strong>LCP</strong></td><td>Largest Contentful Paint</td><td>主内容画出来</td><td>FCP + 图片 / 字体</td></tr><tr><td><strong>INP</strong></td><td>Interaction to Next Paint</td><td>交互的响应快慢</td><td><strong><a href="/Front2Full/manual/computer-programming/ssr/hydration">水合</a> / JS 量</strong></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>对 SSR，TTFB 和 INP 是最能暴露问题的两头。</strong> TTFB 高 → 服务端渲染慢<strong>或缓存没命中</strong>（这是本专栏关注的核心）；INP 差 → JS 太多、<a href="/Front2Full/manual/computer-programming/ssr/hydration">水合</a>太重（这是<a href="/Front2Full/manual/computer-programming/ssr/server-components">流式 / 服务端组件</a>要治的）。中间的 FCP / LCP 是「用户看到内容多快」，是最终体感，但它俩很大程度上被 TTFB 决定——<strong>TTFB 慢，后面全慢</strong>。所以盯 SSR，先盯 TTFB。</p></div><h2 id="ssr-独有的健康指标-缓存命中率" tabindex="-1">SSR 独有的健康指标：缓存命中率 <a class="header-anchor" href="#ssr-独有的健康指标-缓存命中率" aria-label="Permalink to &quot;SSR 独有的健康指标：缓存命中率&quot;">​</a></h2><p>通用性能指标之外，SSR 有一个<strong>别的渲染模式没有、但对你生死攸关</strong>的指标——<strong>缓存命中率(cache hit ratio)</strong>。</p><p><a href="/Front2Full/manual/computer-programming/ssr/why-cache">为什么缓存那章</a> 说过：命中率决定了多少请求真的触发了昂贵的渲染。所以它是 SSR 的<strong>头号健康指标</strong>：</p><ul><li><strong>命中率高（如 95%+）</strong>：绝大多数请求走缓存，源站轻松，TTFB 低而稳。健康。</li><li><strong>命中率突然掉</strong>：几乎一定出事了——可能是<a href="/Front2Full/manual/computer-programming/ssr/cdn-caching">误带了 <code>Set-Cookie</code></a>、<a href="/Front2Full/manual/computer-programming/ssr/http-caching"><code>Vary</code> 太碎</a>、缓存键被查询参数炸开、或某次 <code>purge everything</code>。<strong>命中率是 SSR 的体温计，要有监控和告警。</strong></li></ul><p>命中率从哪看？CDN 的分析面板会给（按 <code>HIT</code> / <code>MISS</code> 状态聚合），或者你自己统计响应里的 <a href="/Front2Full/manual/computer-programming/ssr/cdn-caching"><code>CF-Cache-Status</code> 之类的状态头</a>。</p><h2 id="排查-慢-是服务端还是客户端的锅" tabindex="-1">排查：慢，是服务端还是客户端的锅 <a class="header-anchor" href="#排查-慢-是服务端还是客户端的锅" aria-label="Permalink to &quot;排查：慢，是服务端还是客户端的锅&quot;">​</a></h2><p>用户说「页面慢」，第一步是<strong>定位慢在哪一段</strong>。一个屡试不爽的分诊流程：</p><div class="language-mermaid vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  A[&quot;页面慢&quot;] --&gt; B{&quot;TTFB 高不高&quot;}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  B --&gt;|&quot;高&quot;| C{&quot;缓存命中了吗&quot;}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  C --&gt;|&quot;未命中(MISS/BYPASS)&quot;| D[&quot;缓存问题&lt;br/&gt;查 Set-Cookie / Vary / 缓存键 / Cache-Control&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  C --&gt;|&quot;命中但仍慢&quot;| E[&quot;渲染 / 取数慢&lt;br/&gt;查慢查询 / 慢 API,上数据缓存&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  B --&gt;|&quot;不高&quot;| F{&quot;交互卡不卡(INP 差)&quot;}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  F --&gt;|&quot;卡&quot;| G[&quot;水合 / JS 太重&lt;br/&gt;减少客户端组件,上流式 / RSC&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  F --&gt;|&quot;不卡&quot;| H[&quot;查前端资源:图片 / 字体 / LCP 元素&quot;]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>这套分诊把「慢」精准劈成几类：<strong>TTFB 高且没命中缓存</strong> → 缓存问题（本专栏第三站的排查清单全用得上）；<strong>TTFB 高但命中了</strong> → 渲染 / 取数本身慢（上<a href="/Front2Full/manual/computer-programming/ssr/data-cache">数据缓存</a>、优化查询）；<strong>TTFB 正常但点着卡</strong> → <a href="/Front2Full/manual/computer-programming/ssr/hydration">水合</a>太重（减客户端 JS）；<strong>都正常但 LCP 慢</strong> → 前端资源（图片、字体）的锅。<strong>先分清是「服务端 / 缓存」还是「客户端 / 水合」，再对症下药</strong>，别一上来乱优化。</p><h2 id="实验室-vs-真实用户" tabindex="-1">实验室 vs 真实用户 <a class="header-anchor" href="#实验室-vs-真实用户" aria-label="Permalink to &quot;实验室 vs 真实用户&quot;">​</a></h2><p>测性能有两种数据，别只看一种：</p><ul><li><strong>实验室(lab)</strong>：Lighthouse、WebPageTest——在受控环境跑一遍。方便、可复现，适合开发时调优；但它是<strong>一台机器、一种网络</strong>，不代表真实用户的千差万别。</li><li><strong>真实用户(field / RUM)</strong>：从真实访客采集（Real User Monitoring，或 Google 的 CrUX / Core Web Vitals 报告）。这才是<strong>用户实际体验</strong>——各种设备、各种网络、各种地域（想想<a href="/Front2Full/manual/computer-programming/ssr/edge-rendering">边缘渲染</a>要解决的延迟）。</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>别只信实验室数据。</strong> 你在高端开发机 + 千兆网上 Lighthouse 满分，不代表用户的千元机 + 弱网上不卡。SSR 的很多价值（首屏、缓存命中带来的低 TTFB）恰恰在<strong>弱网、远地域、冷缓存</strong>这些真实场景里才显现——而这些实验室默认测不到。<strong>以真实用户数据（尤其 TTFB 和 INP 的分布，不只看均值，要看 p75 / p95）为准。</strong></p></div><h2 id="小结与下一章" tabindex="-1">小结与下一章 <a class="header-anchor" href="#小结与下一章" aria-label="Permalink to &quot;小结与下一章&quot;">​</a></h2><p>SSR 上生产，盯四个通用指标(TTFB / FCP / LCP / INP)+ 一个专属的头号健康指标（<strong>缓存命中率</strong>）；排查先用「TTFB 高不高 / 命中没 / 交互卡不卡」分诊，把「服务端·缓存」和「客户端·水合」两类问题劈清；数据以<strong>真实用户</strong>为准，别只信实验室。</p><p>到这里，从 CSR 的痛，到 SSR、水合、流式、RSC、边缘，再到整整八章的缓存，最后到量化排查——SSR 的全貌走完了。最后一章，我们用一张「什么页面选什么策略」的决策树，和一份「新手最常踩的坑」清单，把整个专栏收拢。👉 <a href="/Front2Full/manual/computer-programming/ssr/recap">收尾：决策树与常见坑</a>。</p><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li>[1] web.dev.「Core Web Vitals — LCP / INP / TTFB.」<a href="https://web.dev/articles/vitals" target="_blank" rel="noreferrer">https://web.dev/articles/vitals</a> —— 指标定义与阈值。</li><li>[2] Google.「Lab and field data / CrUX.」<a href="https://web.dev/articles/lab-and-field-data-differences" target="_blank" rel="noreferrer">https://web.dev/articles/lab-and-field-data-differences</a> —— 实验室 vs 真实用户。</li><li>[3] Cloudflare.「Analytics — cache hit ratio.」<a href="https://developers.cloudflare.com/analytics/" target="_blank" rel="noreferrer">https://developers.cloudflare.com/analytics/</a> —— 缓存命中率监控。</li></ul>`,25)])])}const h=a(e,[["render",o]]);export{u as __pageData,h as default};
